/**
 * @changelog
 *   v1.0.0 - TOD Phase1 修复：DebugPanel「时间系统(TOD)」面板状态 + 命令式 action 封装。
 *            封装 todModule.xxx(ctx, ...) 实例 API（setTime/getTime/play/pause/setSpeed/
 *            getPlaybackState/getCurrentPhase/getSnapshot/lock/unlockManualOverride/onTimeChanged）。
 *            与 useSkyParams 一致：lazy ctx + try/catch 探测注册；onScopeDispose 自动退订。
 *            REQ: 20260611-tod-system-phase1-fix
 *   v1.1.0 - refreshFromConfig 同步 todModule.getSpeed，修复面板流速恒显示 1（实际配置如 3600 未反映）的问题。
 *            REQ: 20260612-tod-panel-speed-fix
 *   v1.2.0 - 新增 iblIntensity 状态：与 snapshot 同频读取 hdriModule.getEnvironmentIntensity（scene.environmentIntensity），
 *            供 DebugPanel 展示当前 TOD HDRI 的 IBL 亮度；未注册 lighting.hdri 时取不到，置 null（面板提示「未开启」）。
 *            REQ: 20260612-debugpanel-tod-ibl-intensity
 * /@changelog
 *
 * @author DannyCheung
 */
import { reactive, ref, shallowRef, onScopeDispose } from 'vue';
import type { EngineContext, TodSnapshot, TodPhase, TodPlaybackState } from '@tencent/viewer-sdk';
import { todModule, hdriModule } from '@tencent/viewer-sdk';

export interface TodPanelState {
  /** 当前小时（0–24 含小数） */
  hour: number;
  /** 时间流速倍率 */
  speed: number;
  /** 播放状态 */
  playback: TodPlaybackState;
  /** 当前 phase */
  phase: TodPhase | '';
}

/**
 * useTodParams — TOD（时间系统）面板状态 + 命令式 action 封装
 *
 * 设计要点：
 * - lazy ctx + try/catch 探测 todModule 是否注册（未注册时 todEnabled=false，DebugPanel 隐藏分区）
 * - 时间滑块：unlock + pause + setTime（setTime 内部 applyTime 受 manualOverride 阻断，故先 unlock 保证生效）
 * - Sky/太阳/云 手动调参：先 lockForManualEdit（pause + manualOverride），避免 TOD 每帧 applyTime 覆盖
 * - onTimeChanged 订阅：自动播放时实时刷新面板（hour/phase/snapshot），onScopeDispose 退订
 */
export function useTodParams(getCtx: () => EngineContext | undefined) {
  const todEnabled = ref(false);
  const todState = reactive<TodPanelState>({
    hour: 12,
    speed: 1,
    playback: 'paused',
    phase: '',
  });
  /** 当前时刻完整快照（展示该 phase 大气参数）；shallowRef 避免深响应开销 */
  const snapshot = shallowRef<TodSnapshot | null>(null);
  /**
   * 当前 TOD HDRI 的 IBL 亮度（scene.environmentIntensity）。
   * null = 未注册 lighting.hdri（非 HDRI 场景），面板提示「未开启」。
   * TOD 模式下随 phase 切换 / intensity 过渡动态变化，故与 snapshot 同频刷新。
   */
  const iblIntensity = ref<number | null>(null);

  /** 读取当前 IBL 亮度；未注册 hdriModule 时（getEnvironmentIntensity throw）置 null。 */
  function readIblIntensity(ctx: EngineContext): void {
    try {
      iblIntensity.value = hdriModule.getEnvironmentIntensity(ctx);
    } catch {
      iblIntensity.value = null; // 非 HDRI 场景
    }
  }

  let unsubscribe: (() => void) | null = null;

  /**
   * 探测 todModule 是否注册并同步面板状态。
   * @returns true = TOD 已启用；false = 未注册（非 TOD 场景）
   */
  function refreshFromConfig(): boolean {
    const ctx = getCtx();
    if (!ctx) {
      todEnabled.value = false;
      return false;
    }
    try {
      todState.hour = todModule.getTime(ctx);
      todState.speed = todModule.getSpeed(ctx);
      todState.playback = todModule.getPlaybackState(ctx);
      todState.phase = todModule.getCurrentPhase(ctx);
      snapshot.value = todModule.getSnapshot(ctx);
      readIblIntensity(ctx);
      todEnabled.value = true;
      return true;
    } catch {
      todEnabled.value = false;
      return false;
    }
  }

  /** 刷新当前快照与游标（订阅回调 / setTime 后调用） */
  function syncSnapshot(ctx: EngineContext): void {
    try {
      todState.hour = todModule.getTime(ctx);
      todState.phase = todModule.getCurrentPhase(ctx);
      todState.playback = todModule.getPlaybackState(ctx);
      snapshot.value = todModule.getSnapshot(ctx);
      readIblIntensity(ctx);
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  // ======================== 时间 / 速度 / 播放 ========================

  /**
   * 拖动时间滑块：解除手动锁 + 暂停自动播放 + 跳转时间（setTime 受 manualOverride 阻断，故先 unlock）。
   */
  function applyTime(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    try {
      todModule.unlockManualOverride(ctx);
      todModule.pause(ctx);
      todModule.setTime(ctx, todState.hour);
      syncSnapshot(ctx);
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  function applySpeed(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    try {
      todModule.setSpeed(ctx, todState.speed);
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  /** 播放（自动推进时间）：先解除手动锁，再 play */
  function play(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    try {
      todModule.unlockManualOverride(ctx);
      todModule.play(ctx, todState.speed);
      todState.playback = 'playing';
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  function pause(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    try {
      todModule.pause(ctx);
      todState.playback = 'paused';
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  // ======================== 与 Sky/太阳/云 手动调参的互锁 ========================

  /**
   * 进入手动编辑模式（DebugPanel 调 sky/太阳/云 setter 前调用）：暂停 TOD 并阻断 applyTime 覆盖。
   * 非 TOD 场景（todEnabled=false）为 noop。
   */
  function lockForManualEdit(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    try {
      todModule.lockManualOverride(ctx);
      todState.playback = 'paused';
    } catch {
      /* todModule 未注册，忽略 */
    }
  }

  // ======================== onTimeChanged 订阅 ========================

  /**
   * 开始订阅 onTimeChanged（自动播放时实时刷新面板）。重复调用先退订旧的。
   */
  function startSubscription(): void {
    const ctx = getCtx();
    if (!ctx || !todEnabled.value) return;
    stopSubscription();
    try {
      unsubscribe = todModule.onTimeChanged(ctx, (payload) => {
        todState.hour = payload.hour;
        todState.phase = payload.phase;
        snapshot.value = payload.snapshot;
        readIblIntensity(ctx); // IBL 随 phase 切换 / intensity 过渡变化，自动播放时同频刷新
      });
    } catch {
      unsubscribe = null;
    }
  }

  function stopSubscription(): void {
    if (unsubscribe) {
      try {
        unsubscribe();
      } catch {
        /* ignore */
      }
      unsubscribe = null;
    }
  }

  // 组件作用域销毁时自动退订
  onScopeDispose(() => stopSubscription());

  return {
    // state
    todEnabled,
    todState,
    snapshot,
    iblIntensity,
    // actions
    refreshFromConfig,
    applyTime,
    applySpeed,
    play,
    pause,
    lockForManualEdit,
    startSubscription,
    stopSubscription,
  };
}
