/**
 * @changelog
 *   v1.0.0 - 写法 A：纯 inject 范式，对齐 thirdroom 的 useMainThreadContext 写法
 *            （src/ui/hooks/useMainThread.ts）。
 *            ─ React: createContext + useContext + Provider + 抛错守卫
 *            ─ Vue:  Symbol InjectionKey + provide + inject + 抛错守卫
 *
 *            为什么需要 Ref 包裹：viewerSDK.getSceneManager()?.ctx 在 onMounted 异步
 *            await viewerSDK.init(...) 完成之后才有值；用 Ref 包裹后，子组件 inject
 *            到的是同一个 Ref 引用，ctx 就绪后所有消费者自动响应。
 *
 *            为什么提供 useEngineContextGetter：viewer-sdk 的 ECS 模块 API 形如
 *            hdriModule.setEnvironmentIntensity(ctx, v)，是命令式而非响应式调用，
 *            composable（useHdriParams 等）需要在 watch / event handler 内"按需取
 *            最新 ctx"，因此暴露 () => ctx 的 getter 闭包，避免在每个 composable
 *            内手写 inject + .value 拆包。
 *            REQ: viewer-sdk-light-static-to-instance（写法 A）
 *   v2.0.0 - viewer-sdk 单 ctx 合并（GameContext → EngineContext）适配：内部类型引用
 *            统一改为 EngineContext；对外 API 名字保留 GameContext 前缀以避免上游
 *            调用方批量改名。
 *            REQ: 20260601-engine-context-unify TECH: ADR-CTX-001（A1+类型骨架）
 *   v3.0.0 - 语义清零：文件由 useGameContext.ts 重命名为 useEngineContext.ts；
 *            对外 API 全部改名 GameContext* → EngineContext*
 *            （EngineContextKey / provideEngineContext / useEngineContext /
 *            useEngineContextGetter）。所有调用方同步切换。
 *            REQ: 20260601-engine-context-unify TECH: ADR-CTX-001
 * /@changelog
 *
 * @author fancylin
 */
import { inject, provide, type InjectionKey, type Ref } from 'vue';
import type { EngineContext } from '@tencent/viewer-sdk';

/**
 * EngineContext 的注入 key。
 * 值为 Ref<EngineContext | undefined>：viewerSDK 异步初始化后再赋值，初始为 undefined。
 */
export const EngineContextKey: InjectionKey<Ref<EngineContext | undefined>> = Symbol('EngineContext');

/**
 * 在父组件（SceneViewer.vue）setup 顶层调用，向后代提供 EngineContext Ref。
 *
 * 用法：
 * ```ts
 * const engineCtxRef = ref<EngineContext | undefined>(undefined);
 * provideEngineContext(engineCtxRef);
 * onMounted(async () => {
 *   await viewerSDK.init(...);
 *   engineCtxRef.value = viewerSDK.getSceneManager()?.ctx;
 * });
 * ```
 */
export function provideEngineContext(ctxRef: Ref<EngineContext | undefined>): void {
  provide(EngineContextKey, ctxRef);
}

/**
 * 在子组件 setup 顶层调用，inject EngineContext Ref。
 * 找不到 provider 时抛错（对齐 thirdroom useMainThreadContext 的硬守卫语义）。
 *
 * 注意：返回的是 Ref 而非 EngineContext 本身，使用时需 .value 拆包；
 * 多数场景下应改用 useEngineContextGetter() 获得 () => ctx 闭包。
 */
export function useEngineContext(): Ref<EngineContext | undefined> {
  const ctxRef = inject(EngineContextKey);
  if (!ctxRef) {
    throw new Error(
      '[useEngineContext] EngineContext has not been provided. Make sure an ancestor component calls provideEngineContext(ctxRef) in its setup.',
    );
  }
  return ctxRef;
}

/**
 * 返回一个无参 getter：调用时返回当前最新的 EngineContext（可能为 undefined，因为
 * viewerSDK 异步初始化未完成时 ctx 还不存在）。
 *
 * 适用于命令式调用场景（事件回调、watch 回调内向 viewer-sdk 模块 API 透传 ctx）。
 *
 * 用法：
 * ```ts
 * const getCtx = useEngineContextGetter();
 * const { hdriParams } = useHdriParams(getCtx);
 * ```
 */
export function useEngineContextGetter(): () => EngineContext | undefined {
  const ctxRef = useEngineContext();
  return () => ctxRef.value;
}
