import { reactive, ref } from 'vue';
import type { EngineContext } from '@tencent/viewer-sdk';
import { skyModule } from '@tencent/viewer-sdk';

export interface SkyPanelParams {
  turbidity: number;
  rayleigh: number;
  mieCoefficient: number;
  mieDirectionalG: number;
  /** 单位：度 — 0 = 地平线，90 = 天顶 */
  elevation: number;
  /** 单位：度 — 水平方向 */
  azimuth: number;
  /** 视觉太阳圆盘显隐（v1.1.0） */
  showSunDisc: boolean;
  /** SkySun 平行光显隐（v1.1.0，独立于太阳圆盘） */
  sunLightVisible: boolean;
  /** 云噪声尺度（vendored Sky fbm 云，实时生效） */
  cloudScale: number;
  /** 云流动速度（配合 time uniform 漂移） */
  cloudSpeed: number;
  /** 云覆盖度（0=无云） */
  cloudCoverage: number;
  /** 云浓度（云与天空混合权重） */
  cloudDensity: number;
  /** 云高度（云投影平面 + 地平线淡出） */
  cloudElevation: number;
}

/**
 * useSkyParams — Sky 面板状态 + 命令式 action 封装
 *
 * 设计要点：
 * - 与 useHdriParams 一致：lazy ctx + try/catch 探测注册
 * - `enabled` 退化为 UI 展开/折叠局部状态（D-6：运行时无法 register/unregister 子模块；
 *   开关勾选只批量刷新参数；取消勾选仅隐藏 UI）
 * - 不做参数 watch；DebugPanel @change 调单参数 setter
 */
export function useSkyParams(getCtx: () => EngineContext | undefined) {
  const skyParams = reactive<SkyPanelParams>({
    turbidity: 10,
    rayleigh: 3,
    mieCoefficient: 0.005,
    mieDirectionalG: 0.7,
    elevation: 2,
    azimuth: 180,
    showSunDisc: true,
    sunLightVisible: true,
    cloudScale: 0.0002,
    cloudSpeed: 0.0001,
    cloudCoverage: 0.4,
    cloudDensity: 0.4,
    cloudElevation: 0.5,
  });

  /** UI 展开/折叠状态；初始通过 refreshFromConfig 探测 skyModule 是否已注册 */
  const skyEnabled = ref(false);

  /**
   * 从 skyModule 当前 uniforms 同步面板参数。
   * @returns true = 同步成功（skyModule 已注册）；false = skyModule 未注册
   */
  function refreshFromConfig(): boolean {
    const ctx = getCtx();
    if (!ctx) {
      skyEnabled.value = false;
      return false;
    }
    try {
      const u = skyModule.getUniforms(ctx);
      skyEnabled.value = true;
      skyParams.turbidity = u.turbidity;
      skyParams.rayleigh = u.rayleigh;
      skyParams.mieCoefficient = u.mieCoefficient;
      skyParams.mieDirectionalG = u.mieDirectionalG;
      skyParams.elevation = u.elevation;
      skyParams.azimuth = u.azimuth;
      skyParams.showSunDisc = u.showSunDisc;
      skyParams.cloudScale = u.cloudScale;
      skyParams.cloudSpeed = u.cloudSpeed;
      skyParams.cloudCoverage = u.cloudCoverage;
      skyParams.cloudDensity = u.cloudDensity;
      skyParams.cloudElevation = u.cloudElevation;
      skyParams.sunLightVisible = skyModule.isSunLightVisible(ctx);
      return true;
    } catch {
      skyEnabled.value = false;
      return false;
    }
  }

  /**
   * 批量应用当前面板参数（用于预设切换 / 启用开关）。
   * @returns true = 应用成功；false = skyModule 未注册（DebugPanel 应回滚 UI 状态）
   */
  function applyAll(): boolean {
    const ctx = getCtx();
    if (!ctx) return false;
    try {
      skyModule.updateUniforms(ctx, {
        turbidity: skyParams.turbidity,
        rayleigh: skyParams.rayleigh,
        mieCoefficient: skyParams.mieCoefficient,
        mieDirectionalG: skyParams.mieDirectionalG,
        elevation: skyParams.elevation,
        azimuth: skyParams.azimuth,
      });
      return true;
    } catch (err) {
      console.warn('⚠️ skyModule 未注册（需在场景配置中加入 lighting.sky 字段才能启用天空）:', err);
      return false;
    }
  }

  // ======================== 单参数 setter（@change 回调） ========================

  function applyElevation(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setElevation(ctx, skyParams.elevation);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyAzimuth(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setAzimuth(ctx, skyParams.azimuth);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyTurbidity(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setTurbidity(ctx, skyParams.turbidity);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyRayleigh(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setRayleigh(ctx, skyParams.rayleigh);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyMieCoefficient(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setMieCoefficient(ctx, skyParams.mieCoefficient);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyMieDirectionalG(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setMieDirectionalG(ctx, skyParams.mieDirectionalG);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  // ======================== 太阳显隐（v1.1.0） ========================

  function applyShowSunDisc(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setShowSunDisc(ctx, skyParams.showSunDisc);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applySunLightVisible(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setSunLightVisible(ctx, skyParams.sunLightVisible);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  // ======================== 云五参数（vendored Sky fbm 云，实时生效） ========================

  function applyCloudScale(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setCloudScale(ctx, skyParams.cloudScale);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyCloudSpeed(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setCloudSpeed(ctx, skyParams.cloudSpeed);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyCloudCoverage(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setCloudCoverage(ctx, skyParams.cloudCoverage);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyCloudDensity(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setCloudDensity(ctx, skyParams.cloudDensity);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  function applyCloudElevation(): void {
    const ctx = getCtx();
    if (!ctx || !skyEnabled.value) return;
    try {
      skyModule.setCloudElevation(ctx, skyParams.cloudElevation);
    } catch {
      /* skyModule 未注册，忽略 */
    }
  }

  return {
    // state
    skyParams,
    skyEnabled,
    // actions
    refreshFromConfig,
    applyAll,
    applyElevation,
    applyAzimuth,
    applyTurbidity,
    applyRayleigh,
    applyMieCoefficient,
    applyMieDirectionalG,
    applyShowSunDisc,
    applySunLightVisible,
    applyCloudScale,
    applyCloudSpeed,
    applyCloudCoverage,
    applyCloudDensity,
    applyCloudElevation,
  };
}
