/**
 * @changelog
 *   v1.0.0 - 初始实现：后处理（pmndrs/postprocessing）调试面板状态 + 命令式 action 封装。
 *            封装 postProcessingModule.xxx(ctx, ...) 实例 API 的快照读取与 setter，
 *            DebugPanel 仅 import 本 composable，不直接依赖 viewer-sdk 的 PostProcessingModule 类。
 *            REQ: 20260617-postprocessing TECH: postprocessing-pmndrs-integration
 * /@changelog
 *
 * @author DannyCheung
 */
import { reactive, ref } from 'vue';
import type { EngineContext, PmndrsToneMappingMode, SmaaQuality } from '@tencent/viewer-sdk';
import { postProcessingModule } from '@tencent/viewer-sdk';

/** 后处理面板响应式参数（与 DebugPanel 控件双向绑定） */
export interface PostProcessingPanelParams {
  antialiasing: { enabled: boolean; preset: SmaaQuality };
  bloom: { enabled: boolean; intensity: number; luminanceThreshold: number; radius: number };
  ssao: { enabled: boolean; intensity: number; radius: number };
  pmndrsToneMapping: { enabled: boolean; mode: PmndrsToneMappingMode; exposure: number };
}

/**
 * usePostProcessingParams — 后处理面板状态 + 命令式 action 封装
 *
 * 设计要点（对齐 useHdriParams）：
 * - `getCtx()` 工厂返回 `EngineContext | undefined`：sceneManager 可能尚未初始化
 * - 所有 action 内置 try/catch 探测 postProcessingModule 是否注册（配置缺失即未注册）
 * - 走 `@change/@input` 命令式回调，不做 watch 自动同步，避免双向同步隐式行为
 * - `refreshFromConfig` 读取模块当前配置快照写入 reactive params；时机由 DebugPanel 决定
 */
export function usePostProcessingParams(getCtx: () => EngineContext | undefined) {
  /** 后处理是否可用（已注册且 composer 存在） */
  const available = ref(false);

  /** 面板参数 */
  const params = reactive<PostProcessingPanelParams>({
    antialiasing: { enabled: true, preset: 'high' },
    bloom: { enabled: true, intensity: 1.0, luminanceThreshold: 0.9, radius: 0.85 },
    ssao: { enabled: true, intensity: 1.0, radius: 0.1825 },
    pmndrsToneMapping: { enabled: true, mode: 'ACESFilmic', exposure: 1.0 },
  });

  /**
   * 从 postProcessingModule 当前配置快照同步面板参数与可用状态。
   * 未注册（无 renderer.postProcessing 配置）时静默返回 false。
   */
  function refreshFromConfig(): boolean {
    const ctx = getCtx();
    if (!ctx) return false;

    let snapshot;
    try {
      snapshot = postProcessingModule.getConfigSnapshot(ctx);
    } catch {
      available.value = false;
      return false;
    }

    if (!snapshot) {
      available.value = false;
      return false;
    }

    available.value = postProcessingModule.hasComposer(ctx);

    params.antialiasing.enabled = snapshot.antialiasing.enabled;
    params.antialiasing.preset = snapshot.antialiasing.preset;
    params.bloom.enabled = snapshot.bloom.enabled;
    params.bloom.intensity = snapshot.bloom.intensity;
    params.bloom.luminanceThreshold = snapshot.bloom.luminanceThreshold;
    params.bloom.radius = snapshot.bloom.radius;
    params.ssao.enabled = snapshot.ssao.enabled;
    params.ssao.intensity = snapshot.ssao.intensity;
    params.ssao.radius = snapshot.ssao.radius;
    params.pmndrsToneMapping.enabled = snapshot.pmndrsToneMapping.enabled;
    params.pmndrsToneMapping.mode = snapshot.pmndrsToneMapping.mode;
    params.pmndrsToneMapping.exposure = snapshot.pmndrsToneMapping.exposure;

    return available.value;
  }

  // ======================== 命令式 setter（@change / @input 回调） ========================

  function setEffectEnabled(effect: 'antialiasing' | 'bloom' | 'ssao' | 'pmndrsToneMapping', enabled: boolean): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setEffectEnabled(ctx, effect, enabled);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomIntensity(ctx, params.bloom.intensity);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomThreshold(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomThreshold(ctx, params.bloom.luminanceThreshold);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyBloomRadius(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setBloomRadius(ctx, params.bloom.radius);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applySsaoIntensity(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSsaoIntensity(ctx, params.ssao.intensity);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applySsaoRadius(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setSsaoRadius(ctx, params.ssao.radius);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyToneMappingMode(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setToneMappingMode(ctx, params.pmndrsToneMapping.mode);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyToneMappingExposure(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setToneMappingExposure(ctx, params.pmndrsToneMapping.exposure);
    } catch {
      /* 未注册，忽略 */
    }
  }

  function applyAntialiasingPreset(): void {
    const ctx = getCtx();
    if (!ctx) return;
    try {
      postProcessingModule.setAntialiasingPreset(ctx, params.antialiasing.preset);
    } catch {
      /* 未注册，忽略 */
    }
  }

  return {
    // state
    available,
    params,
    // actions
    refreshFromConfig,
    setEffectEnabled,
    applyBloomIntensity,
    applyBloomThreshold,
    applyBloomRadius,
    applySsaoIntensity,
    applySsaoRadius,
    applyToneMappingMode,
    applyToneMappingExposure,
    applyAntialiasingPreset,
  };
}
