const zoneDebugCards = computed(() => {
  const bindingMap = new Map<string, { bgmTrackIds: string[]; sfxTrackIds: string[] }>();

  for (const track of tracks.value) {
    if (!track.zoneId) continue;
    const existing = bindingMap.get(track.zoneId) ?? { bgmTrackIds: [], sfxTrackIds: [] };
    if (track.target === 'bgm') {
      existing.bgmTrackIds.push(track.id);
    } else {
      existing.sfxTrackIds.push(track.id);
    }
    bindingMap.set(track.zoneId, existing);
  }

  return zones.value
    .map((zone) => {
      const bindings = bindingMap.get(zone.id) ?? { bgmTrackIds: [], sfxTrackIds: [] };
      return {
        ...zone,
        bgmTrackIds: bindings.bgmTrackIds,
        sfxTrackIds: bindings.sfxTrackIds,
        linkedTrackCount: bindings.bgmTrackIds.length + bindings.sfxTrackIds.length,
      };
    })
    .sort((a, b) => Number(b.inside) - Number(a.inside) || b.linkedTrackCount - a.linkedTrackCount || a.id.localeCompare(b.id));
});

