 * - v-model 已把本次点击的新值写入 debugConfig[field]
 * - 若新值为 true，则把另一项强制置 false，然后整体 emit
 */
function onColliderVisualToggle(field: 'showColliders' | 'showColliderSolid') {
  const other: 'showColliders' | 'showColliderSolid' =
    field === 'showColliders' ? 'showColliderSolid' : 'showColliders';
  if (debugConfig[field] && debugConfig[other]) {
    debugConfig[other] = false;
  }
  onConfigChange();
}

