function getAudioZoneDebugScene(): THREE.Scene | null {
  if (!props.sceneManager?.getScene) return null;
  try {
    return props.sceneManager.getScene() as THREE.Scene;
  } catch {
    return null;
  }
}

function disposeAudioZoneWireframeObjects(removeFromScene = false): void {
  if (!audioZoneWireframeGroup) return;

  const group = audioZoneWireframeGroup;
  group.children.forEach((child) => {
    const mesh = child as THREE.Mesh;
    mesh.geometry?.dispose?.();
    if (Array.isArray(mesh.material)) {
      mesh.material.forEach((material) => material.dispose());
    } else {
      mesh.material?.dispose?.();
    }
  });
  group.clear();

  if (removeFromScene) {
    group.parent?.remove(group);
    audioZoneWireframeGroup = null;
  }
}

function ensureAudioZoneWireframeGroup(scene: THREE.Scene): THREE.Group {
  if (audioZoneWireframeGroup?.parent === scene) {
    return audioZoneWireframeGroup;
  }

  disposeAudioZoneWireframeObjects(true);

  const group = new THREE.Group();
  group.name = AUDIO_ZONE_WIREFRAME_GROUP_NAME;
  scene.add(group);
  audioZoneWireframeGroup = group;
  return group;
}

function createAudioZoneWireframeMesh(zone: { shape: 'sphere' | 'box'; radius?: number; size?: { x: number; y: number; z: number }; center: { x: number; y: number; z: number }; inside: boolean }): THREE.Mesh {
  const color = zone.inside ? 0x4caf50 : 0x00bcd4;
  const material = new THREE.MeshBasicMaterial({
    color,
    wireframe: true,
    transparent: true,
    opacity: zone.inside ? 0.95 : 0.65,
    depthTest: false,
  });

  const geometry =
    zone.shape === 'sphere'
      ? new THREE.SphereGeometry(Math.max(zone.radius ?? 0.1, 0.1), 16, 12)
      : new THREE.BoxGeometry(
          Math.max(zone.size?.x ?? 0.1, 0.1),
          Math.max(zone.size?.y ?? 0.1, 0.1),
          Math.max(zone.size?.z ?? 0.1, 0.1),
        );

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(zone.center.x, zone.center.y, zone.center.z);
  mesh.name = `AudioZoneWireframe:${zone.shape}`;
  mesh.renderOrder = 1000;
  return mesh;
}

function syncAudioZoneWireframes(): void {
  if (!audioZoneWireframeEnabled.value) return;

  const scene = getAudioZoneDebugScene();
  if (!scene) return;

  const group = ensureAudioZoneWireframeGroup(scene);
  disposeAudioZoneWireframeObjects(false);

  for (const zone of zoneDebugCards.value) {
    group.add(createAudioZoneWireframeMesh(zone));
  }
}

function onAudioZoneWireframeToggle(): void {
  if (audioZoneWireframeEnabled.value) {
    const scene = getAudioZoneDebugScene();
    if (!scene) {
      console.warn('⚠️ SceneManager 未就绪，无法显示 AudioZone 线框');
      audioZoneWireframeEnabled.value = false;
      return;
    }
    syncAudioZoneWireframes();
    return;
  }

  disposeAudioZoneWireframeObjects(true);
}

