function formatZoneShapeMetric(zone: { shape: 'sphere' | 'box'; radius?: number; size?: { x: number; y: number; z: number } }): string {
  if (zone.shape === 'sphere') {
    return `radius=${(zone.radius ?? 0).toFixed(2)}`;
  }

  const { size } = zone;
  if (!size) return 'size=(0.00, 0.00, 0.00)';
  return `size=(${size.x.toFixed(2)}, ${size.y.toFixed(2)}, ${size.z.toFixed(2)})`;
}

/**
 * 复制角色的 Transform（渲染坐标版）到剪贴板
 *
 * position 字段语义 = rebase 后的渲染坐标（= 物理世界中角色实际所处坐标）
 * 如需配置文件 module.transform.position 的"原始世界坐标"，请用「复制角色（偏移前）Transform」按钮
 */
async function copyCharacterTransform() {
  const position = physicsInfo.characterPosition;
  if (!position) {
    alert('无法获取角色位置');
    return;
  }

  const rotation = physicsInfo.characterRotation || { x: 0, y: 0, z: 0 };
  const round2 = (/** @type {number} */ v) => Math.round(v * 100) / 100;

  const transform = {
    position: {
      x: round2(position.x),
      y: round2(position.y),
      z: round2(position.z),
    },
    rotation,
  };

  const transformStr = JSON.stringify(transform, null, 2);

  try {
    await navigator.clipboard.writeText(transformStr);
    console.log('📋 复制的 Transform:', transformStr);
  } catch (err) {
    console.error('复制失败:', err);
  }
}

/**
 * 复制角色的 Transform（偏移前 / 原始世界坐标版）到剪贴板
 *
 * position 字段语义 = 渲染坐标 + worldOffset = 配置文件 module.transform.position 用的坐标系
 * 直接贴回模块配置即可，不需要再手动加偏移量。
 * worldOffset 全 0（rebase 未触发 / debugManager 缺失）时，等价于复制渲染坐标。
 */
async function copyCharacterRawTransform() {
  const position = physicsInfo.characterPosition;
  if (!position) {
    alert('无法获取角色位置');
    return;
  }

  const rotation = physicsInfo.characterRotation || { x: 0, y: 0, z: 0 };
  const worldOffset = props.debugManager?.getWorldOffset?.() ?? { x: 0, y: 0, z: 0 };
  const round2 = (/** @type {number} */ v) => Math.round(v * 100) / 100;

  const renderPosition = {
    x: round2(position.x),
    y: round2(position.y),
    z: round2(position.z),
  };
  const realWorldPosition = {
    x: round2(position.x + worldOffset.x),
    y: round2(position.y + worldOffset.y),
    z: round2(position.z + worldOffset.z),
  };

  const transform = {
    position: realWorldPosition,
    rotation,
  };

  const transformStr = JSON.stringify(transform, null, 2);

  try {
    await navigator.clipboard.writeText(transformStr);
    console.log('📋 复制的 Transform (偏移前):', transformStr);
    console.log('   ├─ 📍 原始世界坐标 (position):', realWorldPosition);
    console.log('   ├─ 🎬 渲染坐标 (renderPosition):', renderPosition);
    console.log('   └─ ↔️ worldOffset:', worldOffset);
  } catch (err) {
    console.error('复制失败:', err);
  }
}

