    const actualConfig = props.physicsWorldManager.getCliffDetectionConfig();
    if (actualConfig) {
      cliffDetectionConfig.enabled = actualConfig.enabled ?? true;
      cliffDetectionConfig.checkDistance = actualConfig.checkDistance ?? 0.35;
      cliffDetectionConfig.maxFallDistance = actualConfig.maxFallDistance ?? 3.0;
      cliffDetectionConfig.safetyMargin = actualConfig.safetyMargin ?? 0.1;
    }
  }

  // 从 sceneManager 获取 HDRI 配置并同步到面板
  initHDRIFromConfig();

  // 从 sceneManager 获取 ToneMapping 配置并同步到面板
  initToneMappingFromConfig();

  // 二次分享开关 OpenID 校验：与 metaverse debug-panel 对齐
  // 必须 openidList 拉取成功 + URL 上有 openid + openidList.includes(openid) 三者全满足才显示开关
  void initSecondShareGate();

  // 初始刷新 lightMesh / lightCulling / lightSchedule 快照
  refreshMeshSnapshot();
  refreshCullingSnapshot();
  refreshScheduleSnapshot();

  // 从 sceneManager 获取后处理配置并同步到面板
  initPostProcessingFromConfig();

  // 监听键盘事件
  const handleKeyDown = (event: KeyboardEvent) => {
    // F1 键切换debug面板
    if (event.key === 'F1') {
      event.preventDefault();
      togglePanel();
    }

    // F2 键切换碰撞体可视化（走互斥逻辑：开启时会自动关闭"显示碰撞体面"）
    if (event.key === 'F2') {
      event.preventDefault();
      debugConfig.showColliders = !debugConfig.showColliders;
      onColliderVisualToggle('showColliders');
    }

    // F3 键切换线框模式
    if (event.key === 'F3') {
      event.preventDefault();
      debugConfig.wireframeMode = !debugConfig.wireframeMode;
      onConfigChange();
    }
  };

  document.addEventListener('keydown', handleKeyDown);

  // 清理函数
  onUnmounted(() => {
    if (updateInterval) {
      clearInterval(updateInterval);
    }
    document.removeEventListener('keydown', handleKeyDown);
  });
});

onUnmounted(() => {
  disposeAudioZoneWireframeObjects(true);
  disposeLightMarkers();
});

watch(
  () => zoneDebugCards.value,
  () => {
    if (audioZoneWireframeEnabled.value) {
      syncAudioZoneWireframes();
    }
  },
  { deep: true },
);

watch(
  () => props.sceneManager,
  () => {
    if (!audioZoneWireframeEnabled.value) return;
    syncAudioZoneWireframes();
  },
);

// 监听 physicsWorldManager 变化，同步悬崖检测配置
watch(
  () => props.physicsWorldManager,
  (newManager) => {
    if (newManager) {
      const actualConfig = newManager.getCliffDetectionConfig();
      if (actualConfig) {
        cliffDetectionConfig.enabled = actualConfig.enabled ?? true;
        cliffDetectionConfig.checkDistance = actualConfig.checkDistance ?? 0.35;
        cliffDetectionConfig.maxFallDistance = actualConfig.maxFallDistance ?? 3.0;
        cliffDetectionConfig.safetyMargin = actualConfig.safetyMargin ?? 0.1;
      }
    }
  },
  { immediate: true },
);

// 监听 sceneManager 变化，同步 HDRI 配置、ToneMapping 配置和 Sky 配置
watch(
  () => props.sceneManager,
  (newManager) => {
    if (newManager) {
      // 使用 onSceneReady 回调，确保场景配置已经加载完成
      newManager.onSceneReady(() => {
        initHDRIFromConfig();
        initToneMappingFromConfig();
        initPostProcessingFromConfig();
        initSkyFromConfig();
        initTodFromConfig();
      });
    }
  },
  { immediate: true },
);
</script>

