<template>
  <div class="audio-panel">
    <div class="audio-panel-header">
      <span class="title">音频</span>
      <button class="mute-btn" :class="{ active: muted }" @click="setMuted(!muted)">
        {{ muted ? '取消静音' : '静音' }}
      </button>
    </div>

    <div v-if="audioCtxState === 'suspended'" class="unlock-tip">点击页面任意位置启用音频</div>

    <div class="slider-row" :class="{ disabled: !bgmEnabled }">
      <input v-model="bgmEnabled" class="channel-toggle" type="checkbox" @change="onBgmToggle" />
      <label>BGM</label>
      <input :value="bgmMasterVolume" type="range" min="0" max="100" step="1" :disabled="!bgmEnabled" @input="onBgmInput" />
      <span>{{ bgmMasterVolume }}%</span>
    </div>

    <div class="slider-row" :class="{ disabled: !sfxEnabled }">
      <input v-model="sfxEnabled" class="channel-toggle" type="checkbox" @change="onSfxToggle" />
      <label>SFX</label>
      <input :value="sfxMasterVolume" type="range" min="0" max="100" step="1" :disabled="!sfxEnabled" @input="onSfxInput" />
      <span>{{ sfxMasterVolume }}%</span>
    </div>
  </div>
</template>

<script setup lang="ts">
/**
 * @changelog
 *   v1.0.0 - Phase6：新增产品级 AudioPanel（BGM/SFX 主音量 + 全局静音 + 解锁提示）。
 *            REQ: 20260527-audio-ecs-module
 *            TECH: audio/plan/phase-6-panels-and-docs
 *   v1.1.0 - 持久化结构升级为 {bgmEnabled, bgmVolume, sfxEnabled, sfxVolume}，
 *            开关与音量两个维度互不污染：关闭只静音引擎，不重置 lastEnabledVolume。
 *            REQ: 20260527-audio-ecs-module
 *            TECH: audio/plan/phase-7-zone-lazy-and-prefs-fix
 * /@changelog
 *
 * @author fancylin
 */
import { onMounted, ref, watch } from 'vue';
import { useEngineContextGetter } from '../composables/useEngineContext';
import { useAudioParams } from '../composables/useAudioParams';

const AUDIO_PREFS_STORAGE_KEY = 'scene-viewer-audio-panel-prefs-v1';
const DEFAULT_VOLUME = 100;

interface AudioPanelPrefs {
  bgmEnabled: boolean;
  bgmVolume: number;
  sfxEnabled: boolean;
  sfxVolume: number;
}

const getCtx = useEngineContextGetter();
const { audioCtxState, bgmMasterVolume, sfxMasterVolume, muted, setBgmMasterVolume, setSfxMasterVolume, setMuted } =
  useAudioParams(getCtx);

// bgm/sfxEnabled 表示「通道开关」，bgm/sfxLastEnabledVolume 表示「用户最近一次启用时的音量」。
// 两个维度独立持久化：关闭开关只把引擎主音量置 0，不动 lastEnabledVolume。
const bgmEnabled = ref(true);
const sfxEnabled = ref(true);
const bgmLastEnabledVolume = ref(DEFAULT_VOLUME);
const sfxLastEnabledVolume = ref(DEFAULT_VOLUME);
const isHydratingPrefs = ref(true);

function clampVolume(volume: number): number {
  return Math.min(100, Math.max(0, volume));
}

function loadAudioPrefs(): AudioPanelPrefs | null {
  try {
    const raw = localStorage.getItem(AUDIO_PREFS_STORAGE_KEY);
    if (!raw) return null;

    const parsed = JSON.parse(raw) as Partial<AudioPanelPrefs>;
    return {
      bgmEnabled: typeof parsed.bgmEnabled === 'boolean' ? parsed.bgmEnabled : true,
      bgmVolume: clampVolume(typeof parsed.bgmVolume === 'number' ? parsed.bgmVolume : DEFAULT_VOLUME),
      sfxEnabled: typeof parsed.sfxEnabled === 'boolean' ? parsed.sfxEnabled : true,
      sfxVolume: clampVolume(typeof parsed.sfxVolume === 'number' ? parsed.sfxVolume : DEFAULT_VOLUME),
    };
  } catch (error) {
    console.warn('[AudioPanel] 读取本地音频设置失败:', error);
    return null;
  }
}

function persistAudioPrefs(): void {
  const prefs: AudioPanelPrefs = {
    bgmEnabled: bgmEnabled.value,
    bgmVolume: clampVolume(bgmLastEnabledVolume.value),
    sfxEnabled: sfxEnabled.value,
    sfxVolume: clampVolume(sfxLastEnabledVolume.value),
  };

  try {
    localStorage.setItem(AUDIO_PREFS_STORAGE_KEY, JSON.stringify(prefs));
  } catch (error) {
    console.warn('[AudioPanel] 保存本地音频设置失败:', error);
  }
}

onMounted(() => {
  const prefs = loadAudioPrefs();
  if (prefs) {
    bgmEnabled.value = prefs.bgmEnabled;
    sfxEnabled.value = prefs.sfxEnabled;
    bgmLastEnabledVolume.value = prefs.bgmVolume;
    sfxLastEnabledVolume.value = prefs.sfxVolume;

    // 关 → 引擎主音量为 0；开 → 用持久化音量
    setBgmMasterVolume(prefs.bgmEnabled ? prefs.bgmVolume : 0);
    setSfxMasterVolume(prefs.sfxEnabled ? prefs.sfxVolume : 0);
  }

  isHydratingPrefs.value = false;
});

watch([bgmEnabled, sfxEnabled, bgmLastEnabledVolume, sfxLastEnabledVolume], () => {
  if (isHydratingPrefs.value) return;
  persistAudioPrefs();
});

function onBgmToggle(): void {
  // 开 → 用 lastEnabledVolume 恢复；关 → 仅静音引擎，不动 lastEnabledVolume
  setBgmMasterVolume(bgmEnabled.value ? bgmLastEnabledVolume.value : 0);
}

function onSfxToggle(): void {
  setSfxMasterVolume(sfxEnabled.value ? sfxLastEnabledVolume.value : 0);
}

function onBgmInput(event: Event): void {
  const volume = clampVolume(Number((event.target as HTMLInputElement).value));
  setBgmMasterVolume(volume);
  // 仅在 >0 时刷新 lastEnabledVolume，使其始终代表「最近一次有效音量」
  if (volume > 0) bgmLastEnabledVolume.value = volume;
}

function onSfxInput(event: Event): void {
  const volume = clampVolume(Number((event.target as HTMLInputElement).value));
  setSfxMasterVolume(volume);
  if (volume > 0) sfxLastEnabledVolume.value = volume;
}
</script>

